import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'

const hash = value => createHash('sha256').update(value).digest('hex')
const base = 'e125813da6aa6a211f36d2248a877e10dc0efd45'
const candidate = '4ab408b75747b2fadc195a85db82ee6f18ec721f'
const root = '/workspace/pnd-baseline-144-selection'
const changed = new Set(['app/scene-entities.ts', 'app/scene.ts', 'app/selection-runtime.ts'])
const load = name => {
  const receipt = JSON.parse(readFileSync(`work/orchestration/${name}`, 'utf8'))
  assert.equal(receipt.phase, 'finished')
  assert.deepEqual(receipt.source, receipt.sourceAfter)
  for (const stream of ['stdout', 'stderr']) {
    assert.equal(hash(receipt[stream]), receipt[`${stream}Sha256`])
    assert.equal(hash(readFileSync(receipt.artifacts[stream])), receipt[`${stream}Sha256`])
  }
  return receipt
}
const full = load('issue144-selection-focused-4ab408b.json')
const previous = load('issue144-selection-baseline-focused-e125813.json')
assert.equal(full.source.headOid, candidate)
assert.equal(previous.source.headOid, base)
assert.equal(full.status, 'passed')
assert.equal(full.exitCode, 0)
assert.equal(previous.status, 'failed')
assert.equal(previous.exitCode, 1)
assert.deepEqual(full.command, previous.command)
assert.deepEqual(Object.keys(full.source.inputs), Object.keys(previous.source.inputs))
for (const [path, digest] of Object.entries(full.source.inputs)) {
  assert.equal(hash(readFileSync(path)), digest, path)
  assert.equal(hash(readFileSync(`${root}/${path}`)), previous.source.inputs[path], path)
  if (!changed.has(path)) assert.equal(digest, previous.source.inputs[path], path)
}
assert.match(full.stdout, /pass 7\n.*fail 0/)
assert.match(previous.stdout, /pass 5\n.*fail 2/)
assert.match(previous.stdout, /wrapper must forward an explicitly empty set/)
assert.match(previous.stdout, /quiet idle full unit caller read 4160 selected slots for 64 people/)
assert.equal(
  execFileSync('git', ['diff', '--name-only', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
  ''
)
assert.equal(previous.source.trackedDiffSha256, hash(''))
const original = path => execFileSync('git', ['show', `${base}:${path}`], { encoding: 'utf8' })
for (const path of changed) assert.equal(hash(original(path)), previous.source.inputs[path])
const restore = (value, from, to) => {
  assert.ok(value.includes(from), from)
  assert.equal(value.split(from).length, 2, 'the explicit source transformation must occur once')
  return value.replace(from, to)
}
let entities = readFileSync('app/scene-entities.ts', 'utf8')
entities = restore(entities, 'const unitFrameSelectedIds = new WeakMap<GameScene, Set<number>>()\n', '')
entities = restore(entities, 'frameNumber?: number,\n  selectedIds?: ReadonlySet<number>', 'frameNumber?: number')
entities = restore(
  entities,
  `        selectionFlags:
          (selectedIds?.has(g.userData.unit) ?? scene.world.selected.includes(g.userData.unit))
            ? 128
            : 0,`,
  '        selectionFlags: scene.world.selected.includes(g.userData.unit) ? 128 : 0,'
)
entities = restore(
  entities,
  `  let selectedIds = unitFrameSelectedIds.get(scene)
  if (!selectedIds) {
    selectedIds = new Set()
    unitFrameSelectedIds.set(scene, selectedIds)
  }
  selectedIds.clear()
  for (const id of scene.world.selected) selectedIds.add(id)
`,
  ''
)
entities = restore(entities, 'unitAnimation(scene.world, u, selectedIds)', 'unitAnimation(scene.world, u)')
entities = restore(
  entities,
  'nativeDirections ? animationSource!.f2 : undefined,\n      selectedIds',
  'nativeDirections ? animationSource!.f2 : undefined'
)
assert.equal(entities, original('app/scene-entities.ts'))
let scene = readFileSync('app/scene.ts', 'utf8')
scene = restore(scene, 'frameNumber?: number,\n    selectedIds?: ReadonlySet<number>', 'frameNumber?: number')
scene = restore(
  scene,
  'animatePerson(this, g, heading, directions, age, once, frameNumber, selectedIds)',
  'animatePerson(this, g, heading, directions, age, once, frameNumber)'
)
assert.equal(scene, original('app/scene.ts'))
let selection = readFileSync('app/selection-runtime.ts', 'utf8')
selection = restore(
  selection,
  'unitAnimation(w: World, u: Unit, selectedIds?: ReadonlySet<number>)',
  'unitAnimation(w: World, u: Unit)'
)
selection = restore(
  selection,
  "return (selectedIds?.has(u.id) ?? w.selected.includes(u.id)) ? 'selected' : 'idle'",
  "return w.selected.includes(u.id) ? 'selected' : 'idle'"
)
assert.equal(selection, original('app/selection-runtime.ts'))
const lint = load('issue144-selection-oxlint-4ab408b.json')
const oldLint = load('issue144-selection-baseline-oxlint-e125813.json')
for (const receipt of [lint, oldLint]) {
  assert.equal(receipt.status, 'failed')
  assert.equal(receipt.exitCode, 1)
}
assert.equal(lint.source.headOid, candidate)
assert.equal(oldLint.source.headOid, base)
assert.deepEqual(lint.command, oldLint.command)
for (const [path, digest] of Object.entries(lint.source.inputs))
  if (!changed.has(path)) assert.equal(digest, oldLint.source.inputs[path], path)
const diagnostics = receipt => receipt.stdout.trim().split('\n')
  .map(line => line.replace(/:\d+:\d+(?=: (?:warning|error))/, ':<line>:<column>')).sort()
assert.equal(diagnostics(lint).length, 28)
assert.deepEqual(diagnostics(lint), diagnostics(oldLint))
console.log(JSON.stringify({
  focusedCandidate: 'passed 7/7',
  actualUnmodifiedBase: 'failed: five unchanged lifecycle/default cases passed; new explicit-set authority and scaling failed',
  baseScaling: '4160 selected-slot reads for64 people; bound128',
  pairedInputHashes: full.source.inputs,
  productionBaseUnchanged: true,
  allSourceOutsideExplicitMembershipAndOptionalForwardingUnchanged: true,
  strictOxlintCandidate: 'failed',
  strictOxlintBase: 'failed',
  diagnosticMultiset: 'passed:28 inherited diagnostics (24warnings/4errors); only numeric line/column prefixes normalized',
  scalingScope: 'quiet all-selected legacy idle people, both idle-state and arrow consumers; selected-slot reads only, no whole-frame/native/browser/hardware timing claim',
}, null, 2))
